#include <sys/stat.h>

int main(int argc, char **argv){
  const char *p = argc>1?argv[1]:"/run/am4/cfg";
  struct file_handle *h = malloc(sizeof(struct file_handle)+256);
  int mount_id;
  h->handle_bytes=256;
  if(name_to_handle_at(AT_FDCWD,p,h,&mount_id,0)){
    perror("name_to_handle_at"); return 1;
  }
  printf("handle_bytes=%u type=%d mount_id=%d\n",h->handle_bytes,h->handle_type,mount_id);
  for(unsigned i=0;i<h->handle_bytes;i++) printf("%02x",h->f_handle[i]); printf("\n");
  int fd=open_by_handle_at(AT_FDCWD,h,O_RDONLY|O_DIRECTORY);
  if(fd<0){perror("open_by_handle_at"); return 2;}
  printf("fd=%d\n",fd);
  char buf[4096];
  int n=read(fd,buf,sizeof(buf)-1);
  if(n>=0){buf[n]=0; printf("READ:\n%s\n",buf);} else perror("read");
  int pfd=openat(fd,"..",O_RDONLY|O_DIRECTORY);
  if(pfd<0){perror("openat ..");return 3;}
  printf("parent fd=%d\n",pfd);
  int n2=read(pfd,buf,sizeof(buf)-1);
  if(n2>=0){buf[n2]=0; printf("PARENT READ:\n%s\n",buf);} else perror("read parent");
  return 0;
}
EOF
