#define _GNU_SOURCE
#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/stat.h>
#ifndef OPEN_TREE_CLONE
#define OPEN_TREE_CLONE 1
#endif
static void listfd(int fd,const char*tag){
 char c[512]; ssize_t m=readlink("/proc/self/fd/%d",c,511); if(m>0){c[m]=0;printf("  [%s] -> %s\n",tag,c);} else printf("  [%s] readlink errno=%d %s\n",tag,errno,strerror(errno));
 int dfd=openat(fd,".",O_RDONLY|O_DIRECTORY);
 if(dfd<0){printf("  [%s] openat . errno=%d %s\n",tag,errno,strerror(errno));return;}
 DIR*d=fdopendir(dfd); if(!d){perror("fdopendir");close(dfd);return;}
 struct dirent*e; int k=0; while((e=readdir(d))&&k<50){printf("  [%s] %s\n",tag,e->d_name);k++;}
 closedir(d);
}
int main(int argc,char**argv){
 const char*path=argc>1?argv[1]:"/";
 int flags=argc>2?atoi(argv[2]):OPEN_TREE_CLONE;
 long r=syscall(428, AT_FDCWD, path, flags);
 printf("open_tree(%s,flags=%d)=%ld errno=%d %s\n",path,flags,r,errno,strerror(errno));
 if(r<0)return 1;
 listfd(r,"clone");
 const char* rels[]={".","..","../..","../../..","dev","run","app","proc","sys","tmp",".containerenv",NULL};
 for(int i=0;rels[i];i++){
   int fd=openat(r,rels[i],O_PATH);
   printf("openat %s = %d errno=%d %s\n",rels[i],fd,errno,strerror(errno));
   if(fd>=0){listfd(fd,rels[i]);close(fd);}
 }
 return 0;
}
EOF
